fn normalize_path(path: &str, resolve_symlinks: bool) -> String {
    let p = Path::new(path);
    let abs_path = if p.is_absolute() {
        p.to_path_buf()
    } else {
        env::current_dir().unwrap_or_else(|_| PathBuf::from(".")).join(p)
    };

    if resolve_symlinks {
        if let Ok(canon) = fs::canonicalize(&abs_path) {
            return canon.to_string_lossy().to_string();
        }
    } else {
        // Just clean the path (resolve . and .. without resolving symlinks if possible)
        // But for now, canonicalize is easier. zoxide usually resolves anyway if it exists.
        if let Ok(canon) = fs::canonicalize(&abs_path) {
            return canon.to_string_lossy().to_string();
        }
    }

    abs_path.to_string_lossy().to_string()
}

fn matches_keywords(path: &str, keywords: &[String]) -> bool {
    if keywords.is_empty() {
        return true;
    }

    let path_lc = path.to_lowercase();
    let last_kw = keywords.last().unwrap().to_lowercase();

    let mut start = 0;
    let mut last_match_indices = Vec::new();
    while let Some(pos) = path_lc[start..].find(&last_kw) {
        let abs_pos = start + pos;
        let end_pos = abs_pos + last_kw.len();
        if !path_lc[end_pos..].contains('/') {
            last_match_indices.push(abs_pos);
        }
        start = abs_pos + 1;
    }

    if last_match_indices.is_empty() {
        return false;
    }

    for &last_pos in &last_match_indices {
        let mut current_pos = 0;
        let mut matched_all = true;
        for i in 0..keywords.len() - 1 {
            let kw = keywords[i].to_lowercase();
            if let Some(pos) = path_lc[current_pos..last_pos].find(&kw) {
                current_pos += pos + kw.len();
            } else {
                matched_all = false;
                break;
            }
        }
        if matched_all {
            return true;
        }
    }

    false
}

