            let db = Database::load(&get_data_dir().join("db.zo")).unwrap_or_else(|_| Database { entries: Vec::new() });
            let mut matches: Vec<&Entry> = db.entries.iter()
                .filter(|e| matches_keywords(&e.path, &keywords))
                .filter(|e| exclude.as_ref().map_or(true, |ex| &e.path != ex))
                .filter(|e| all || Path::new(&e.path).exists())
                .collect();
            matches.sort_by(|a, b| b.score.partial_cmp(&a.score).unwrap().then(b.timestamp.cmp(&a.timestamp)));
            if list { for e in matches { if score { println!("{:>7.1} {}", e.score * 4.0, e.path); } else { println!("{}", e.path); } } }
            else if let Some(e) = matches.first() { if env::var("_ZO_ECHO") == Ok("1".to_string()) { eprintln!("{}", e.path); } println!("{}", e.path); }
            else { eprintln!("zoxide: no match found"); process::exit(1); }
        }
        "remove" => {
            let mut i = 2;
            let mut paths = Vec::new();
            while i < args.len() {
                if args[i] == "-h" || args[i] == "--help" { println!("zoxide-remove 0.9.9\nAjeet D'Souza <98ajeet@gmail.com>\nhttps://github.com/ajeetdsouza/zoxide\n\nRemove a directory from the database\n\nUsage:\n  executable remove [PATHS]...\n\nArguments:\n  [PATHS]...\n\nOptions:\n  -h, --help     Print help\n  -V, --version  Print version"); return; }
                if !args[i].starts_with('-') { paths.push(normalize_path(&args[i], false)); }
                i += 1;
            }
            let db_path = get_data_dir().join("db.zo");
            let mut db = Database::load(&db_path).unwrap_or_else(|_| Database { entries: Vec::new() });
            let initial = db.entries.len();
            db.entries.retain(|e| !paths.contains(&e.path));
            if db.entries.len() == initial && !paths.is_empty() {
                for p in paths { if !db.entries.iter().any(|e| e.path == p) { eprintln!("zoxide: path not found in database: {}", p); break; } }
            }
            db.save(&db_path).unwrap();
        }
        "init" => {
            let (mut shell, mut cmd) = ("", "z");
            let mut i = 2;
            while i < args.len() {
                if args[i] == "--cmd" && i + 1 < args.len() { cmd = &args[i+1]; i += 1; }
                else if !args[i].starts_with('-') { shell = &args[i]; }
                i += 1;
            }
            let mut s = get_init_script(shell).to_string();
            if cmd != "z" {
                s = s.replace(" z ", &format!(" {} ", cmd)).replace(" z()", &format!(" {}()", cmd)).replace("=z", &format!("={}", cmd))
                    .replace("unalias z", &format!("unalias {}", cmd)).replace(" -- z", &format!(" -- {}", cmd))
                    .replace(" zi ", &format!(" {}i ", cmd)).replace(" zi()", &format!(" {}i()", cmd)).replace("unalias zi", &format!("unalias {}i", cmd));
            }
            print!("{}", s);
        }
        "import" => {
            let (mut from, mut merge, mut path) = ("", false, "");
            let mut i = 2;
            while i < args.len() {
                if args[i] == "--from" && i + 1 < args.len() { from = &args[i+1]; i += 1; }
                else if args[i] == "--merge" { merge = true; }
                else if !args[i].starts_with('-') { path = &args[i]; }
                i += 1;
            }
            let db_path = get_data_dir().join("db.zo");
            let mut db = Database::load(&db_path).unwrap_or_else(|_| Database { entries: Vec::new() });
            if from == "z" {
                if let Ok(f) = File::open(path) {
                    for line in BufReader::new(f).lines() {
                        if let Ok(l) = line {
                            let p: Vec<&str> = l.split('|').collect();
                            if p.len() == 3 {
                                let (path, score, ts) = (p[0].to_string(), p[1].parse().unwrap_or(0.0), p[2].parse().unwrap_or(0));
                                if merge { if let Some(e) = db.entries.iter_mut().find(|e| e.path == path) { e.score += score; if ts > e.timestamp { e.timestamp = ts; } continue; } }
                                db.entries.push(Entry { path, score, timestamp: ts });
                            }
                        }
                    }
                }
            }
            db.save(&db_path).unwrap();
        }
        "edit" => { eprintln!("zoxide: could not find fzf, is it installed?"); process::exit(1); }
        _ => { print_help(); }
    }
}
fn get_data_dir() -> PathBuf {
    if let Ok(d) = env::var("_ZO_DATA_DIR") { PathBuf::from(d) }
    else if let Ok(d) = env::var("XDG_DATA_HOME") { PathBuf::from(d).join("zoxide") }
    else if let Ok(h) = env::var("HOME") { PathBuf::from(h).join(".local/share/zoxide") }
    else { PathBuf::from(".") }
}
fn print_help() { println!("zoxide 0.9.9\nAjeet D'Souza <98ajeet@gmail.com>\nhttps://github.com/ajeetdsouza/zoxide\n\nA smarter cd command for your terminal\n\nUsage:\n  executable <COMMAND>\n\nCommands:\n  add     Add a new directory or increment its rank\n  edit    Edit the database\n  import  Import entries from another application\n  init    Generate shell configuration\n  query   Search for a directory in the database\n  remove  Remove a directory from the database\n\nOptions:\n  -h, --help     Print help\n  -V, --version  Print version"); }
EOF
cat init_scripts.rs >> src/main.rs
./compile.sh
"}
